/* Discoverable business configuration; saved locally, shared by prototype consumers. */
const businessRulesLegacyEditor=window.openSalesPolicy;
let businessRulesView='pricing',businessRuleStatus='active';
function businessRulesData(){
 ensureRecordWorkspace();
 if(!state.businessRules){
  const rate=configValueByKey('valuation_fattening_rate'),weight=configValueByKey('reporting_weight_35');
  const legacySales={...state.sales};
  const sourceValue=(item,fallback)=>item&&((item.revision||1)>1||(item.sourceValue!==undefined&&item.value!==item.sourceValue))?item.value:fallback??item?.value;
  const next=BusinessRulesModel.migrateLegacy({...legacySales,rate:sourceValue(rate,legacySales.rate),weight:sourceValue(weight,legacySales.weight)},state.salesPolicyPreview,entityRegistryData());
  next.legacySalesSource=legacySales;businessRulesPersist(next);
 }
 return state.businessRules;
}
function businessRuleName(kind,id){return EntityRegistryModel.rows(entityRegistryData(),kind).find(r=>r.id===id)?.name||'All';}
function businessRuleOptions(kind,selected='',species=''){return '<option value="">All</option>'+EntityRegistryModel.rows(entityRegistryData(),kind).filter(r=>r.active&&(!species||kind!=='breeds'||r.parentId===species)).map(r=>`<option value="${esc(r.id)}" ${r.id===selected?'selected':''}>${esc(r.name)}</option>`).join('');}
function businessRuleFields(rule,global=false){const g=businessRulesData().global,dis=canEdit()?'':'disabled';return `${global?'':`<div class="br-grid"><label>Animal type<select id="br-species" onchange="businessRuleBreedChange()" ${dis}>${businessRuleOptions('species',rule.speciesId)}</select></label><label>Breed<select id="br-breed" ${dis}>${businessRuleOptions('breeds',rule.breedId,rule.speciesId)}</select></label><label>Sex<select id="br-sex" ${dis}>${businessRuleOptions('sex_values',rule.sexId)}</select></label></div>`}<div class="br-grid"><label>Price / valuation rate<input id="br-rate" type="number" min="0.01" step="any" value="${rule.rate??''}" placeholder="${g.rate}" ${dis}></label><label>Price basis<select id="br-unit" ${dis}>${(global?['INR/kg']:['INR/kg','INR/animal']).map(u=>`<option value="${u}" ${(rule.unit||g.unit)===u?'selected':''}>${u==='INR/kg'?'₹ per kg':'₹ per animal'}</option>`).join('')}</select></label><label>Minimum weight (kg)<input id="br-weight" type="number" min="0.001" step="any" value="${rule.weightKg??''}" placeholder="${g.weightKg}" ${dis}></label><label>Allowed shortfall (g)<input id="br-shortfall" type="number" min="0" max="1000" step="1" value="${rule.shortfallKg==null?'':Math.round(rule.shortfallKg*1000)}" placeholder="${Math.round(g.shortfallKg*1000)}" ${dis}></label><label>Weight comparison<select id="br-comparison" ${dis}><option value=">=" ${(rule.comparison||g.comparison)==='>='?'selected':''}>At least (≥)</option><option value=">" ${(rule.comparison||g.comparison)==='>'?'selected':''}>Greater than (&gt;)</option></select></label><label>Group availability<select id="br-enabled" ${dis}><option value="true" ${rule.enabled!==false?'selected':''}>Enabled</option><option value="false" ${rule.enabled===false?'selected':''}>Not enabled for sale</option></select></label></div><p class="br-help">35 kg with a 500 g shortfall means a 34.5 kg effective threshold. This is not a ± measurement-error setting.${global?'':' Leave numeric fields blank to inherit defaults.'}</p>`;}
function businessRuleBreedChange(){document.querySelector('#br-breed').innerHTML=businessRuleOptions('breeds','',document.querySelector('#br-species').value);}
function businessRuleEdit(id='new'){
 const m=businessRulesData(),r=id==='global'?m.global:m.overrides.find(r=>r.id===id)||{};
 modal(id==='global'?'Default pricing and weight rule':id==='new'?'Add animal-group rule':'Animal-group rule',`<form onsubmit="event.preventDefault();businessRuleSave('${id}')">${businessRuleFields(r,id==='global')}${id==='global'?`<label class="br-sharing"><input id="br-sharing" type="checkbox" ${m.shareWeighing!==false?'checked':''} ${canEdit()?'':'disabled'}> Share these rules with Weighing</label>`:''}<p id="br-error" class="error" role="alert"></p><div class="br-actions">${id!=='global'&&id!=='new'&&canEdit()?`<button type="button" onclick="businessRuleArchive('${id}')">${r.active===false?'Restore':'Archive'} rule</button>`:''}<button type="button" onclick="closeModal()">Cancel</button>${canEdit()?'<button class="primary" type="submit">Save rule</button>':''}</div></form>`,true);document.querySelector('#overlay .modal')?.classList.add('br-dialog');
}
function businessRulesPersist(next){
 state.businessRules=next;
 // Preserve existing scalar consumers and their stable config identities.
 const values={reporting_weight_35:next.global.weightKg,valuation_fattening_rate:next.global.rate};
 for(const [key,value] of Object.entries(values)){const item=configValueByKey(key);if(item){item.value=value;item.revision=(item.revision||0)+1;}}
 state.sales={...state.sales,weight:next.global.weightKg,margin:next.global.shortfallKg,rate:next.global.rate,comparison:next.global.comparison,version:next.version};
 persist();
}
function businessRuleSave(id){if(!canEdit())return;try{
 const number=(key,scale=1)=>{const el=document.querySelector('#br-'+key);if(el.validity?.badInput)throw Error('Enter a valid number.');return el.value.trim()===''?null:Number(el.value)/scale;};
 const input={rate:number('rate'),unit:document.querySelector('#br-unit').value,weightKg:number('weight'),shortfallKg:number('shortfall',1000),comparison:document.querySelector('#br-comparison').value,enabled:document.querySelector('#br-enabled').value==='true'};
 let next;
 if(id==='global'){next=structuredClone(businessRulesData());next.global=input;next.shareWeighing=document.querySelector('#br-sharing')?.checked??next.shareWeighing!==false;next.version++;const errors=BusinessRulesModel.validate(next,entityRegistryData());if(errors.length)throw Error(errors.join(' '));const lower=configValueByKey('reporting_weight_30');if(lower&&input.weightKg<=lower.value)throw Error('Upper reporting weight must exceed the lower reporting weight.');}
 else next=BusinessRulesModel.upsert(businessRulesData(),{...input,...(id==='new'?{}:{id}),speciesId:document.querySelector('#br-species').value,breedId:document.querySelector('#br-breed').value,sexId:document.querySelector('#br-sex').value,active:id==='new'?true:businessRulesData().overrides.find(r=>r.id===id)?.active!==false},entityRegistryData());
 businessRulesPersist(next);closeModal();render();toast('Business rules saved in this browser');
 }catch(e){document.querySelector('#br-error').textContent=e.message;}}
function businessRuleArchive(id){if(!canEdit())return;try{const model=businessRulesData(),r=model.overrides.find(r=>r.id===id),next=r.active===false?BusinessRulesModel.upsert(model,{...r,active:true},entityRegistryData()):BusinessRulesModel.archive(model,id);businessRulesPersist(next);closeModal();render();}catch(e){document.querySelector('#br-error').textContent=e.message;}}
function businessRulesPricing(){const m=businessRulesData(),g=m.global,rows=m.overrides.filter(r=>businessRuleStatus==='all'||(r.active!==false)===(businessRuleStatus==='active'));return `<div class="br-section-title"><div><h2>Pricing and weight rules</h2><p>Defaults apply unless a more specific animal-group rule matches.</p></div><button class="primary" onclick="businessRuleEdit()" ${canEdit()?'':'disabled'}>+ Add group rule</button></div><div class="br-default" role="button" tabindex="0" aria-label="Open default pricing and weight rule" onclick="businessRuleEdit('global')" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();this.click()}"><div><small>Default price / valuation</small><strong>₹${g.rate.toLocaleString('en-IN')} <span>${g.unit==='INR/kg'?'/ kg':'/ animal'}</span></strong></div><div><small>Minimum weight</small><strong>${g.weightKg} <span>kg</span></strong></div><div><small>Allowed shortfall</small><strong>${Math.round(g.shortfallKg*1000)} <span>g</span></strong></div><div><small>Effective threshold</small><strong>${esc(g.comparison)} ${Number((g.weightKg-g.shortfallKg).toFixed(3))} <span>kg</span></strong></div><span aria-hidden="true">›</span></div><div class="br-table-heading"><h3>Animal-group overrides</h3><label>Status<select aria-label="Rule status" onchange="businessRuleStatus=this.value;render()">${['active','archived','all'].map(s=>`<option ${s===businessRuleStatus?'selected':''}>${s}</option>`).join('')}</select></label></div><div class="records-table-wrap"><table class="records-table"><thead><tr><th>Animal type</th><th>Breed</th><th>Sex</th><th>Price</th><th>Weight</th><th>Shortfall</th><th>Status</th></tr></thead><tbody>${rows.map(r=>`<tr class="record-row" tabindex="0" aria-label="Open ${esc(businessRuleName('species',r.speciesId))} ${esc(businessRuleName('breeds',r.breedId))} ${esc(businessRuleName('sex_values',r.sexId))} rule" onclick="businessRuleEdit('${r.id}')" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();this.click()}"><td>${esc(businessRuleName('species',r.speciesId))}</td><td>${esc(businessRuleName('breeds',r.breedId))}</td><td>${esc(businessRuleName('sex_values',r.sexId))}</td><td>${r.rate==null?'Default':'₹'+r.rate} ${r.unit==='INR/animal'?'/ animal':'/ kg'}</td><td>${r.weightKg==null?'Default':r.weightKg+' kg'}</td><td>${r.shortfallKg==null?'Default':Math.round(r.shortfallKg*1000)+' g'}</td><td>${r.active===false?'Archived':r.enabled===false?'Disabled':'Active'}</td></tr>`).join('')||'<tr><td colspan="7" class="empty">No group rules. The default applies to every animal.</td></tr>'}</tbody></table></div><p class="br-help">Matching uses animal type, breed and sex. Ambiguous rules are rejected. Saved changes apply to Sales${m.shareWeighing!==false?' and the Weighing preview':''}.</p>`;}
function businessRulesOther(){ensureTypedConfig();return `<h2>Operational settings</h2><p>Existing settings and valuation assumptions, with their responsible module.</p><div class="records-table-wrap"><table class="records-table"><thead><tr><th>Setting</th><th>Value</th><th>Responsible module</th></tr></thead><tbody>${state.items.filter(i=>i.itemKind==='config_value'&&i.active&&!['reporting_weight_35','valuation_fattening_rate'].includes(i.configKey)).map(i=>`<tr class="record-row" tabindex="0" onclick="businessSettingEdit('${i.id}')" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();this.click()}"><td>${esc(i.name)}</td><td>${esc(configDisplayValue(i))}</td><td>${esc(i.sourceOwner)}</td></tr>`).join('')}</tbody></table></div>`;}
function businessSettingEdit(id){const i=itemById(id);if(!i)return;const readOnly=!canEdit()||i.sourceKind==='derived_reference';const control=i.valueType==='boolean'?`<select id="bs-value" ${readOnly?'disabled':''}><option value="true" ${i.value===true?'selected':''}>Yes</option><option value="false" ${i.value===false?'selected':''}>No</option></select>`:i.valueType==='enum'?`<select id="bs-value" ${readOnly?'disabled':''}>${(i.enumOptions||[]).map(v=>`<option ${v===i.value?'selected':''}>${esc(v)}</option>`).join('')}</select>`:`<input id="bs-value" value="${esc(String(i.value))}" ${readOnly?'disabled':''}>`;modal(i.name,`<form onsubmit="event.preventDefault();businessSettingSave('${id}')"><label>Value · ${esc(i.unit)}${control}</label><p class="br-help">Used by ${esc((i.shares||[]).join(', '))} · ${esc(typedConfigSourceLabels[i.sourceKind]||i.sourceKind)}</p><p id="bs-error" class="error" role="alert"></p><div class="br-actions"><button type="button" onclick="closeModal()">Close</button>${readOnly?'':'<button class="primary">Save setting</button>'}</div></form>`);}
function businessSettingSave(id){if(!canEdit())return;try{const old=itemById(id);if(!old||old.sourceKind==='derived_reference')throw Error('This setting is read only.');const next={...old,value:typedConfigValue(old.valueType,document.querySelector('#bs-value').value)};const error=validateTypedConfig(next,old);if(error)throw Error(error);if(next.configKey==='reporting_weight_30'&&next.value>=businessRulesData().global.weightKg)throw Error('Lower reporting weight must be below the upper weight.');Object.assign(old,next,{revision:(old.revision||0)+1});persist();closeModal();render();}catch(e){document.querySelector('#bs-error').textContent=e.message;}}
function businessRuleCheckMarkup(){return `<section class="br-check"><h2>Check an animal</h2><p>Uses the saved rule version ${businessRulesData().version}. This check does not create or approve a sale.</p><div class="br-grid"><label>Animal type<select id="bc-species" onchange="document.querySelector('#bc-breed').innerHTML=businessRuleOptions('breeds','',this.value)">${businessRuleOptions('species')}</select></label><label>Breed<select id="bc-breed">${businessRuleOptions('breeds')}</select></label><label>Sex<select id="bc-sex">${businessRuleOptions('sex_values')}</select></label><label>Measured weight (kg)<input id="bc-weight" type="number" step="any" min="0.001" value="34.5"></label></div><button onclick="businessRuleCheck()">Check saved rule</button><div id="bc-result" role="status" class="br-result"></div></section>`;}
function businessRuleCheck(){try{const raw=document.querySelector('#bc-weight').value;if(!raw.trim())throw Error('Enter a measured weight.');const r=BusinessRulesModel.evaluate(businessRulesData(),{speciesId:document.querySelector('#bc-species').value,breedId:document.querySelector('#bc-breed').value,sexId:document.querySelector('#bc-sex').value,weight:Number(raw),weightUnit:'kg'},entityRegistryData());document.querySelector('#bc-result').textContent=`${r.eligible?'Meets':'Does not meet'} the saved weight rule · effective threshold ${r.rule.comparison} ${r.effectiveThresholdKg} kg · indicative value ₹${Number(r.valuation).toLocaleString('en-IN')} · ${r.overrideId?'Animal-group override':'Default rule'}`;}catch(e){document.querySelector('#bc-result').textContent=e.message;}}
function renderBusinessRules(module='Configuration'){
 let m;try{m=businessRulesData();}catch(e){document.querySelector('#main').innerHTML=`<section class="business-rules-page"><h1>Review existing rules</h1><p role="alert">${esc(e.message)}</p><p>Your existing settings are preserved. Correct the saved animal-group references before continuing.</p><button onclick="businessRulesLegacyEditor()">Review saved policy</button></section>`;return;}if(module==='Weighing'&&m.shareWeighing===false){document.querySelector('#main').innerHTML='<section class="business-rules-page"><h1>Weight rules</h1><p>Sales has not shared these rules with Weighing.</p><a href="#/configuration/business-rules">Manage business rules</a></section>';return;}document.querySelector('#main').innerHTML=`<section class="business-rules-page"><div class="records-heading"><div><span class="eyebrow">${esc(module)} · Business rules</span><h1>Pricing, weights and settings</h1><p>Saved locally · version ${m.version} · used by Sales${m.shareWeighing!==false?' and Weighing':''}</p></div></div><nav class="br-tabs" aria-label="Business rule sections"><button class="${businessRulesView==='pricing'?'active':''}" onclick="businessRulesView='pricing';render()">Pricing & weights</button><button class="${businessRulesView==='other'?'active':''}" onclick="businessRulesView='other';render()">Other settings</button></nav><section class="br-panel">${businessRulesView==='other'?businessRulesOther():businessRulesPricing()}</section>${businessRulesView==='pricing'?businessRuleCheckMarkup():''}<p class="br-help">₹450/kg is the existing fattening valuation assumption. These editable rules are prototype proposals; recorded transaction prices and production enforcement remain unchanged.</p></section>`;
}
const businessRulesRenderConsumer=window.renderConsumerSurface;
window.renderConsumerSurface=function(module,label){
 if(label==='Business rules'||label==='Weight rules'){renderBusinessRules(module);return true;}
 if((module==='Sales'&&label==='Farm value')||(module==='Weighing'&&label==='ADG Analytics')){
  const result=businessRulesRenderConsumer(module,label),el=document.querySelector('#content');
  try{const m=businessRulesData();el.insertAdjacentHTML('beforeend',`<section class="business-rules-page"><div class="br-section-title"><div><h2>Saved business rule preview</h2><p>Rule version ${m.version}</p></div><a href="#/configuration/business-rules">Business rules</a></div>${module==='Weighing'&&m.shareWeighing===false?'<p>Sales has not shared these rules with Weighing.</p>':businessRuleCheckMarkup()}<p class="br-help">This is a local rule check. Historical sales and measured weights are not modified.</p></section>`);}catch(e){el.insertAdjacentHTML('beforeend',`<p role="alert">${esc(e.message)} <a href="#/configuration/business-rules">Review business rules</a></p>`);}return result;
 }
 return businessRulesRenderConsumer(module,label);
};
// Older entry points lead to the same editor rather than an independent policy copy.
window.openSalesPolicy=function(){productionNavigate('Sales','Business rules');};
window.salesPolicyTry=function(){productionNavigate('Sales','Farm value');};
